    	/* 팝업 -> 오늘 그만보기 쿠키 설정 */
    	function fnPopupTodayStop(){

    		var cookie_name = "popupUseAt";
    		var value = "N";
    		var cookie_value = "";
    		var date  = new Date();
    		date.setDate(date.getDate() +1 );
    		var expiresDate = new Date(date.toISOString().split('T')[0]);
    		cookie_value += cookie_name+"=N;";
    		cookie_value += "expires=" + expiresDate.toGMTString();
    		document.cookie = cookie_value;

    		closePopupWindow();	//팝업 레이어 닫기
    	}

    	// 쿠키 가져오기
    	function getCookie() {
            var cName = "popupUseAt";
            var cookieData = document.cookie;
            var start = cookieData.indexOf(cName);
            var cValue = '';
            if(start != -1){
                start += cName.length;
                var end = cookieData.indexOf(';', start);
                if(end == -1)end = cookieData.length;
                cValue = cookieData.substring(start, end);
            }
            console.log("cValue : " + cValue);

            if ( cValue != "=N"){
				$("#popup-window").attr("style","display:block");
            } else {
            	return false;
            }
            return unescape(cValue);
        }

